// Enhanced pipeline success handler with detailed feedback
const timestamp = new Date().toLocaleString();
const outputLines = msg.payload.split('\n');

// Parse output for statistics
let stats = {
    races_processed: 0,
    models_trained: 0,
    ratings_generated: 0,
    predictions_made: 0,
    data_mb: 0
};

// Extract statistics from output
outputLines.forEach(line => {
    if (line.includes('races processed')) {
        const match = line.match(/(\d+)\s+races?\s+processed/i);
        if (match) stats.races_processed = parseInt(match[1]);
    }
    if (line.includes('model') && line.includes('trained')) {
        stats.models_trained++;
    }
    if (line.includes('rating') && line.includes('generated')) {
        const match = line.match(/(\d+)\s+rating/i);
        if (match) stats.ratings_generated = parseInt(match[1]);
    }
    if (line.includes('prediction')) {
        stats.predictions_made++;
    }
});

// Calculate data size
stats.data_mb = (msg.payload.length / 1024 / 1024).toFixed(2);

// Create enhanced feedback message
