// Enhanced pipeline error handler with diagnostics
const timestamp = new Date().toLocaleString();
const errorOutput = msg.payload || 'Unknown error';

// Parse error for common issues
let errorType = 'Unknown Error';
let solution = 'Check logs for details';

if (errorOutput.includes('Permission denied')) {
    errorType = 'Permission Error';
    solution = 'Check file permissions and user access';
} else if (errorOutput.includes('No such file')) {
    errorType = 'File Not Found';
    solution = 'Verify script paths and file locations';
} else if (errorOutput.includes('Connection')) {
    errorType = 'Database Connection Error';
    solution = 'Check database connectivity and credentials';
} else if (errorOutput.includes('Memory')) {
    errorType = 'Memory Error';
    solution = 'Reduce data batch size or increase system memory';
} else if (errorOutput.includes('Import')) {
    errorType = 'Python Module Error';
    solution = 'Install missing Python dependencies';
}

